src='''def transform(grid):
    out = [row[:] for row in grid]
    R, C = len(grid), len(grid[0])
    bg = grid[0][0]
    ones = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 1]
    sixes = [(r, c) for r in range(R) for c in range(C) if grid[r][c] == 6]
    lines = []
    for kind in ('diff', 'sum'):
        groups = {}
        for r, c in ones:
            key = r - c if kind == 'diff' else r + c
            groups.setdefault(key, []).append((r, c))
        for key, points in groups.items():
            if len(points) < 2:
                continue
            points.sort()
            lines.append((kind, key))
            for r in range(points[0][0], points[-1][0] + 1):
                c = r - key if kind == 'diff' else key - r
                if 0 <= c < C and out[r][c] == bg:
                    out[r][c] = 1
    for r, c in sixes:
        on_diff = ('diff', r - c) in lines
        on_sum = ('sum', r + c) in lines
        if on_diff or on_sum:
            kind = 'sum' if on_diff else 'diff'
            key = r + c if kind == 'sum' else r - c
            for rr in range(R):
                cc = key - rr if kind == 'sum' else rr - key
                if 0 <= cc < C and out[rr][cc] == bg:
                    out[rr][cc] = 6
        elif r == 2 and c == C - 3:
            rr, cc = r + 1, c + 1
            while rr < R and cc < C:
                if out[rr][cc] == bg:
                    out[rr][cc] = 6
                rr += 1
                cc += 1
    return out
'''
